-- title:  Wavy Navy (tic-80 classic port)
-- author: Dave Templin (original by Rodney McAuley / Sirius Software 1983)
-- desc:   Classic port of the 1983 apple ii game
-- script: lua
-- saveid: davetemplin_wavynavy

-- Code lives in the .lua modules beside this cart, loaded at run time by the
-- require lines below -- launch TIC-80 from this folder so they resolve (see
-- README.md). This code section stays a bare entry stub: game logic belongs in
-- the modules, and the asset chunks below are mastered here, edited in TIC-80's
-- own editors.

-- debug
start_lives=4 -- starting lives (4); LDA #$04 / STA LIVES ($668D, per-player LIVES $4746)
start_wave=1 -- starting wave number (1-start, 2-mines, 3-bombers, 4-cruise missiles, 10-last rank); (WAVENUM $472B)
pcm_enabled=true -- use to test with or without PCM samples (true = PCM, false = SFX fallback)

require "constants"
require "helpers"
require "a2boot"
require "sfx"
require "pcm"
require "waves"
require "explode"
require "dive"
require "boat"
require "bombs"
require "enemies"
require "hazards"
require "status"
require "state_title"
require "state_attract"
require "state_ready"
require "state_play"
require "state_clear"
require "state_gameover"
require "game_state"

-- load saved hiscore/difficulty/display mode, enter the title and start the power-on intro
function BOOT()
 hi = pmem(0)
 diff = clamp(0, pmem(1), 2) -- 0 beginner / 1 advanced / 2 expert
 mono.load() -- display mode from pmem(2): 0 colour / 1 green / 2 white
 demo = false
 title_t = 0
 goto_title()
 apple2.boot{skip = true, rgb = mono.fg(), bg_rgb = mono.bg()} -- power-on intro
end

-- per display frame: intro, sound upkeep, then the live state's update and draw
function TIC()
 if not game_update then BOOT() end -- some embedded players skip BOOT()
 if apple2.tic() then return end -- the Apple II boot sequence owns the frame,
                                 -- the PCM channel included: it plays the Disk
                                 -- II drive sound from its own bank and hands
                                 -- the channel back at the silence level
 pcm.update() -- every frame from then on: the engine clears the PCM buffer
              -- each TIC, so silence must be written too, and the version
              -- probe + midpoint ramp run off this call
 hf_pull() -- one queued heli-gunfire report per frame (sfx.lua): every round
           -- is heard, and the spacing never merges two into one blip
 game_update()
 game_draw()
 mono.apply() -- monochrome-monitor post-process (no-op in colour mode)
end

